import {noteSections,escapeHtml} from './core.js';
export function renderNotebook(notes,isDemo){const input=(key,label,hint)=>`<label class="note-sub-label" for="note-${key}">${label||''}</label><textarea id="note-${key}" data-note="${key}" aria-label="${escapeHtml(label||noteSections.find(s=>s.key===key)?.label||key)}" placeholder="${escapeHtml(hint||'整理原文、記下你的理解…')}">${escapeHtml(notes[key]||'')}</textarea>`;
document.querySelector('#notebook-body').innerHTML=noteSections.map((s,i)=>`<details class="note-section" ${i===0?'open':''}><summary><span class="note-number">0${i+1}</span>${s.label}</summary>${i===0&&isDemo?'<div class="note-example"><strong>示範閱讀提示 · 第 1 頁</strong>注意力如何幫助模型取得相關上下文？這份示範短文沒有提供實驗數據，請區分概念說明與研究證據。</div>':''}${s.children?s.children.map(([k,l])=>input(k,l)).join(''):input(s.key,'',s.hint)}</details>`).join('')+`<details class="note-section" open><summary><span class="note-number">↳</span>原文摘錄 <span class="count">${notes.quotes?.length||0}</span></summary><div id="quotes-list">${(notes.quotes||[]).map(q=>`<div class="quote-card"><p>${escapeHtml(q.text)}</p><button data-source-page="${q.page}">↗ 第 ${q.page} 頁 · 回到原文</button><button class="quote-remove" data-remove-quote="${q.id}" aria-label="刪除此摘錄">移除</button></div>`).join('')||'<p class="note-example">選取原文後，按「加入筆記」收藏重要段落。</p>'}</div></details>`;
}
export function noteCount(notes){return Object.entries(notes).filter(([k,v])=>k!=='quotes'&&typeof v==='string'&&v.trim()).length+(notes.quotes?.length||0);}
